prompt --application/shared_components/navigation/lists/dynamic_navigation_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(7072233998161364624)
,p_name=>'Dynamic Navigation Menu'
,p_static_id=>'dynamic-navigation-menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH USER_ACCESS AS (',
'    SELECT DISTINCT',
'        NM.MENU_ID,',
'        NM.PARENT_MENU_ID,',
'        NM.MENU_NAME,',
'        NM.MENU_SEQ_ID,',
'        -- COALESCE(NM.ICON_CLASS, NM.ICON, ''fa-file-o'') AS ICON_DISPLAY,',
'        TRIM(',
'            NVL(NM.ICON, ''fa-file-o'') || '' '' ||',
'            NVL(NM.ICON_CLASS, '''')',
'        ) AS ICON_DISPLAY,',
'        PM.APEX_PAGE_ID',
'    FROM DEMO_USER_MASTER U',
'    JOIN DEMO_USER_ROLE_ACCESS_MASTER URA ON U.USER_ID = URA.USER_ID',
'    JOIN DEMO_ROLE_MASTER R ON URA.ROLE_ID = R.ROLE_ID',
'    JOIN DEMO_ROLE_PAGE_ACCESS_MASTER RPA ON R.ROLE_ID = RPA.ROLE_ID',
'    JOIN DEMO_PAGE_MASTER PM ON RPA.PAGE_ID = PM.PAGE_ID',
'    JOIN DEMO_NAVIGATION_MENU_MASTER NM ON PM.PAGE_ID = NM.PAGE_ID',
'    WHERE U.USER_ID = TO_NUMBER(:APP_USER_ID)',
'    AND RPA.ROLE_ID = TO_NUMBER(:APP_ROLE_ID)',
'    AND URA.ROLE_ID = TO_NUMBER(:APP_ROLE_ID)',
'    AND U.IS_ACTIVE = ''Y''',
'    AND URA.IS_ACTIVE = ''Y''',
'    AND R.IS_ACTIVE = ''Y''',
'    AND RPA.IS_ACTIVE = ''Y''',
'    AND PM.IS_ACTIVE = ''Y''',
'    AND NM.IS_ACTIVE = ''Y''',
'),',
'ALL_MENUS AS (',
'    SELECT MENU_ID, PARENT_MENU_ID, MENU_NAME, MENU_SEQ_ID, ICON_DISPLAY, APEX_PAGE_ID FROM USER_ACCESS',
'    UNION',
'    SELECT NM.MENU_ID, NM.PARENT_MENU_ID, NM.MENU_NAME, NM.MENU_SEQ_ID, COALESCE(NM.ICON_CLASS,',
'NM.ICON, ''fa-folder-o''), NM.APEX_PAGE_ID',
'    FROM DEMO_NAVIGATION_MENU_MASTER NM',
'    WHERE NM.IS_ACTIVE = ''Y''',
'        AND NM.MENU_ID IN (SELECT DISTINCT PARENT_MENU_ID FROM USER_ACCESS WHERE PARENT_MENU_ID IS NOT',
'NULL)',
')',
'SELECT',
'    LEVEL AS "LEVEL",',
'    MENU_NAME AS LABEL,',
'    CASE WHEN APEX_PAGE_ID IS NOT NULL THEN',
'        APEX_PAGE.GET_URL(P_APPLICATION => :APP_ID, P_PAGE => TO_CHAR(APEX_PAGE_ID), P_SESSION',
'=> :APP_SESSION)',
'    ELSE NULL END AS TARGET,',
'    CASE WHEN APEX_PAGE_ID = :APP_PAGE_ID THEN ''YES'' ELSE ''NO'' END AS IS_CURRENT_LIST_ENTRY,',
'    ICON_DISPLAY AS IMAGE,',
'    NULL AS IMAGE_ATTRIBUTE,',
'    NULL AS IMAGE_ALT_ATTRIBUTE,',
'    TO_CHAR(MENU_ID) AS ATTRIBUTE1',
'FROM ALL_MENUS',
'START WITH PARENT_MENU_ID IS NULL',
'CONNECT BY PRIOR MENU_ID = PARENT_MENU_ID',
'ORDER SIBLINGS BY MENU_SEQ_ID NULLS LAST;'))
,p_version_scn=>'SH256:tKBICJrK6Rdpy38jszsPd40J-NE3jAkwUyfKiYDAigA'
,p_created_on=>wwv_flow_imp.dz('20261023063808Z')
,p_updated_on=>wwv_flow_imp.dz('20261026061542Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
