wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3305703504302975749)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ROLE-WISE HOME PAGE'
,p_static_id=>'role-wise-home-page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    L_TARGET_APEX_PAGE_ID    NUMBER;',
'    L_TARGET_PAGE_ALIAS      VARCHAR2(255 CHAR);',
'    L_REDIRECT_URL           VARCHAR2(4000 CHAR);',
'    L_CURRENT_PAGE_ID        NUMBER := NVL(:APP_PAGE_ID, 1);',
'BEGIN',
'    BEGIN',
'        SELECT PM.APEX_PAGE_ID',
'        INTO L_TARGET_APEX_PAGE_ID',
'        FROM DEMO_ROLE_HOME_PAGES RHP',
'        JOIN DEMO_PAGE_MASTER PM ON RHP.HOME_PAGE_ID = PM.PAGE_ID',
'        WHERE RHP.ROLE_ID = TO_NUMBER(:APP_ROLE_ID)',
'            AND RHP.IS_ACTIVE = ''Y''',
'            AND PM.IS_ACTIVE = ''Y'';',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            L_TARGET_APEX_PAGE_ID := 1;',
'    END;',
'',
'    IF L_TARGET_APEX_PAGE_ID IS NOT NULL AND L_TARGET_APEX_PAGE_ID != L_CURRENT_PAGE_ID THEN',
'        BEGIN',
'            SELECT LOWER(PAGE_ALIAS)',
'            INTO L_TARGET_PAGE_ALIAS',
'            FROM APEX_APPLICATION_PAGES',
'            WHERE APPLICATION_ID = :APP_ID',
'                AND PAGE_ID = L_TARGET_APEX_PAGE_ID;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                L_TARGET_PAGE_ALIAS := TO_CHAR(L_TARGET_APEX_PAGE_ID);',
'        END;',
'',
'        L_REDIRECT_URL := APEX_PAGE.GET_URL (',
'            P_APPLICATION   => :APP_ID,',
'            P_PAGE          => NVL(L_TARGET_PAGE_ALIAS, TO_CHAR(L_TARGET_APEX_PAGE_ID)),',
'            P_SESSION       => :APP_SESSION',
'        );',
'',
'        APEX_UTIL.REDIRECT_URL(P_URL => L_REDIRECT_URL);',
'        APEX_APPLICATION.STOP_APEX_ENGINE;',
'    END IF;',
'EXCEPTION',
'    WHEN APEX_APPLICATION.E_STOP_APEX_ENGINE THEN',
'        RAISE;',
'    WHEN OTHERS THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3305703504302975749
,p_created_on=>wwv_flow_imp.dz('20261023060948Z')
,p_updated_on=>wwv_flow_imp.dz('20261023060948Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
